const invertSquare = (square: cg.Key): cg.Key => {
  const asPos = util.key2pos(square);
  return util.pos2keyUnsafe([asPos[0], 7 - asPos[1]] as cg.Pos);
};

const invertPieces = (pieces: cg.Pieces): cg.Pieces =>
